import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new THREE.Group();
  const timelines = [];

  // Color palette
  const colors = {
    bg: new THREE.Color('#0b0b10'),
    accent: new THREE.Color('#ff2a38'),
  };

  // ===== BACKDROP PLANE (7 x 5.5, z=-1.5) =====
  const backdropGeom = new THREE.PlaneGeometry(7, 5.5);
  const backdropMat = new THREE.MeshBasicMaterial({
    color: colors.bg,
  });
  const backdrop = new THREE.Mesh(backdropGeom, backdropMat);
  backdrop.position.z = -1.5;
  root.add(backdrop);

  // ===== CAPTION KICKER (y=1.15) =====
  const captionGroup = ctx.fontAtlas.createText('NOVA ATELIER / CALIBRE PROGRAM', {
    font: 'JetBrains Mono',
    size: 18,
    weight: 700,
    letterSpacing: 0.12,
    lineHeight: 1.4,
  });
  captionGroup.position.y = 1.15;
  root.add(captionGroup);

  // ===== HERO TEXT (y=0.4, per-word z offsets: 0.12 / 0.0) =====
  const heroGroup = ctx.fontAtlas.createText('TIME, MACHINED.', {
    font: 'Lora',
    size: 124,
    weight: 600,
    letterSpacing: -0.01,
    lineHeight: 1.05,
  });
  heroGroup.position.y = 0.4;

  // Apply per-word z offsets: "TIME," (idx 0-4) = 0.12, "MACHINED." (idx 5+) = 0.0
  if (heroGroup.children) {
    heroGroup.children.forEach((glyph, idx) => {
      glyph.position.z = idx < 5 ? 0.12 : 0.0;
    });
  }

  root.add(heroGroup);

  // ===== ACCENT UNDERLINE (2.6 x 0.045, y=-0.05, z=0.15) =====
  const underlineGeom = new THREE.PlaneGeometry(2.6, 0.045);
  const underlineMat = new THREE.MeshBasicMaterial({
    color: colors.accent,
    emissive: colors.accent,
    emissiveIntensity: 1.2,
  });
  const underline = new THREE.Mesh(underlineGeom, underlineMat);
  underline.position.y = -0.05;
  underline.position.z = 0.15;
  underline.scale.x = 0; // Will animate to 1
  underline.geometry.translate(-1.3, 0, 0); // Left-anchor for scaleX animation
  root.add(underline);

  // ===== SUBHEAD TEXT (y=-0.65, initial offset +0.2 for fade-up) =====
  const subheadGroup = ctx.fontAtlas.createText('Every calibre begins as a solid billet.', {
    font: 'JetBrains Mono',
    size: 40,
    weight: 400,
    letterSpacing: 0.02,
    lineHeight: 1.35,
  });
  subheadGroup.position.y = -0.45; // Start at -0.65 + 0.2

  if (subheadGroup.children) {
    subheadGroup.children.forEach((glyph) => {
      if (glyph.material) {
        glyph.material.transparent = true;
        glyph.material.opacity = 0;
      }
    });
  }

  root.add(subheadGroup);

  // ===== APPLY KINETIC-TEXT PRIMITIVE =====
  if (ctx.primitives && typeof ctx.primitives['kinetic-text'] === 'function') {
    ctx.primitives['kinetic-text'](heroGroup, {
      staggerMs: 60,
      riseUnits: 0.35,
    });
  }

  // ===== POST-KINETIC TIMELINE =====
  // Hero completes when: (numGlyphs - 1) * 60ms stagger + 700ms animation
  const numHeroGlyphs = heroGroup.children ? heroGroup.children.length : 14;
  const heroCompletionTime = (numHeroGlyphs - 1) * 0.06 + 0.7;
  const underlineStartTime = heroCompletionTime + 0.12;

  const timeline = gsap.timeline({ paused: false });
  timelines.push(timeline);

  // Group weighted-settle: scale 1.04 -> 1.0, 900ms
  timeline.to(
    heroGroup.scale,
    {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.9,
      ease: 'cubic-bezier(0.165,0.84,0.44,1)',
    },
    heroCompletionTime
  );
  heroGroup.scale.set(1.04, 1.04, 1.04);

  // Underline scaleX: 0 -> 1, 500ms, starts 120ms after hero completes
  timeline.to(
    underline.scale,
    {
      x: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    },
    underlineStartTime
  );

  // Subhead fade-up: y position +0.2 -> 0, opacity 0 -> 1, 500ms
  timeline.to(
    subheadGroup.position,
    {
      y: -0.65,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    },
    heroCompletionTime
  );

  if (subheadGroup.children) {
    subheadGroup.children.forEach((glyph) => {
      timeline.to(
        glyph.material,
        {
          opacity: 1,
          duration: 0.5,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        },
        heroCompletionTime
      );
    });
  }

  // ===== CLEANUP =====
  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());

    backdropGeom.dispose();
    backdropMat.dispose();
    underlineGeom.dispose();
    underlineMat.dispose();

    [captionGroup, heroGroup, subheadGroup].forEach((group) => {
      if (group.children) {
        group.children.forEach((child) => {
          if (child.geometry) child.geometry.dispose();
          if (child.material) child.material.dispose();
        });
      }
    });
  };

  return root;
}
